from typing import Annotated, Self
from pydantic import BaseModel, ConfigDict, Field, field_validator, model_validator, ValidationError

class CreateUserIn(BaseModel):
    model_config = ConfigDict(extra='forbid', str_strip_whitespace=True)

    email: Annotated[str, Field(max_length=320)]
    display_name: Annotated[str, Field(min_length=1, max_length=80)]
    age: Annotated[int, Field(ge=13, le=130)] | None = None

    @field_validator('email')
    @classmethod
    def email_lower(cls, v: str) -> str:
        if '@' not in v:
            raise ValueError('invalid email')
        return v.lower()

    @model_validator(mode='after')
    def business_rules(self) -> Self:
        # cross-field rules here
        return self

class UserOut(BaseModel):
    model_config = ConfigDict(from_attributes=True)
    id: str
    email: str
    display_name: str

def parse_body(raw: bytes) -> CreateUserIn:
    try:
        return CreateUserIn.model_validate_json(raw)
    except ValidationError as e:
        # map e.errors() to HTTP 422 at the web layer
        raise
